<template><div v-if="auth.isLoggedIn" class="notif-wrap"><button class="notification" @click="open=!open">🔔<span v-if="unread" class="notif-count">{{unread>9?'9+':unread}}</span></button><div v-if="open" class="notif-pop"><div class="notif-head"><b>Notifications</b><button class="ghost" @click="markAll">Mark all read</button></div><div v-if="items.length"><div v-for="n in items" :key="n._id" class="notice" :class="{unread:!n.read}" @click="read(n)"><b>{{n.title}}</b><p>{{n.message}}</p><small>{{new Date(n.createdAt).toLocaleString()}}</small></div></div><div v-else class="empty">No notifications yet.</div><div v-if="error" class="error" style="margin-top:8px">{{error}}</div></div></div></template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import {useAuth} from '../stores/auth';import {api} from '../services/api';const auth=useAuth(),open=ref(false),items=ref<any[]>([]),unread=ref(0),error=ref('');async function load(){try{const d=await api.get('/me/notifications');items.value=d.data||[];unread.value=d.unread||0}catch{}}
// These used to fire the request with no try/catch at all: a failed click just did
// nothing (unhandled rejection, no user feedback, no rollback). Now they optimistically
// update and roll back with a message if the request actually fails.
async function read(n:any){if(n.read)return;error.value='';const was=n.read;n.read=true;unread.value=Math.max(0,unread.value-1);try{await api.patch(`/me/notifications/${n._id}/read`,{})}catch(e:any){n.read=was;unread.value++;error.value=e?.message||'Could not mark as read.'}}
async function markAll(){error.value='';const prev=items.value.map(n=>n.read),prevUnread=unread.value;items.value.forEach(n=>n.read=true);unread.value=0;try{await api.patch('/me/notifications/read-all',{})}catch(e:any){items.value.forEach((n,i)=>n.read=prev[i]);unread.value=prevUnread;error.value=e?.message||'Could not mark all as read.'}}
onMounted(load)</script>
